  ui_story_5086_50860100_5_dialog_content = "ถึงเวลาที่ฉันต้องไปสู่จุดสำคัญที่ถูกกำหนดโดยชะตากรรมแล้ว",
  ui_story_5086_50860100_6_dialog_content = "เพราะฉะนั้น ได้โปรด...",
