  ui_story_5086_50860100_20_dialog_content = "ขออภัยที่ต้องบอกคุณ แต่คุณพลาดโอกาสแล้ว ละครสัตว์ได้ยกค่ายและออกเดินทางไปสองสามวันที่แล้ว",
