  ui_story_5086_50860100_24_dialog_content = "ทุกคนรู้ว่าหัวหน้าคณะละครสัตว์ได้เกิดการทะเลาะวิวาทกับคู่รักของเขา ดังนั้นเขาจึงออกเรือไปค้นหาเขา!",
  ui_story_5086_50860100_25_dialog_content = "อะไร? ฉันคิดว่าเพราะมีสัตว์มหัศจรรย์หนีออกจากเรือ!",
  ui_story_5086_50860100_26_dialog_content = "คุณทุกคนเห็นมันไหม? ปลาวาฬใหญ่โตนั้นนำทางเลย!",
  ui_story_5086_50860100_27_dialog_content = "เอาล่ะ พวกเขาก็รีบร้อนออกไป... นั่นแน่นอน.",
  ui_story_5086_50860100_28_dialog_content = "ฉันแค่หวังว่าไม่มีอะไรเลวร้ายเกิดขึ้น",
  ui_story_5086_50860100_29_dialog_content = "ฉันควรจะหาเจโน่ที่ไหนดีล่ะตอนนี้?",
  ui_story_5086_50860100_30_dialog_content = "จดหมายไม่ได้กล่าวว่า... รอสักครู่ มีที่อยู่เขียนอยู่ด้านหลัง! คิดว่าฉันคงไม่ได้สังเกตเห็นมันก่อนหน้านี้",
  ui_story_5086_50860100_31_dialog_content = "ถนนปะการัง 130—",
  ui_story_5086_50860100_32_dialog_content = "ยินดีต้อนรับสู่สวนสนุกใต้ทะเลของเมืองฮาร์เบอร์ สถานที่ที่ฝันและทะเลมาพบกัน!",
  ui_story_5086_50860100_33_dialog_content = "คุณอยากว่ายน้ำกับฉลามไหม?",
  ui_story_5086_50860100_34_dialog_content = "หรืออาจจะพักผ่อนและสนุกกับเต่าทะเลก็ได้นะ?",
  ui_story_5086_50860100_35_dialog_content = "คุณยังสามารถเข้าร่วมกับแมงกะพรุนและเป่าฟองสบู่สวยๆได้ด้วย!",
  ui_story_5086_50860100_36_dialog_content = "ทุกสิ่งเป็นไปได้ในสถานที่ที่น่าทึ่งนี้!",
  ui_story_5086_50860100_37_dialog_content = "... อควาเรียมเหรอ?",
  ui_story_5086_50860100_38_dialog_content = "ถูกต้องค่ะ, อควาเรียมเนี่ย!",
  ui_story_5086_50860100_39_dialog_content = "เรามีสัตว์น้ำน่ารักทุกชนิดที่แน่นอนว่าจะทำให้คุณหลงรัก! นี่คือครั้งแรกของคุณที่นี่หรือไม่?",
  ui_story_5086_50860100_40_dialog_content = "ถ้างั้น ข้าพเจ้าขอแนะนำให้เริ่มจากด้านซ้ายของชั้น 1...",
  ui_story_5086_50860100_41_dialog_content = "เออ... ที่นั่นมีอะไรแสดงอีกหรอ? ขอโทษนะ ฉันมีความจำระยะสั้นที่แย่มาก ขอฉันตรวจสอบบันทึกของฉันก่อน...",
  ui_story_5086_50860100_42_dialog_content = "เอ่อ, ฉันไม่ได้มาที่นี่เพื่อ-",
  ui_story_5086_50860100_43_dialog_content = "อะฮ่า, นั่นมันอยู่ที่นี่! นี่คือนิทรรศการปะการังรีฟ!",
  ui_story_5086_50860100_44_dialog_content = "วันนี้เรายังจัดงานอีเวนต์ที่มีการโต้ตอบด้วย! ลูกค้าสามารถสัมผัสปลาดาวได้ที่นั่น ในขณะที่ลูกเล็กเด็กแดงอายุไม่เกินสิบปีเข้าชมฟรี!",
  ui_story_5086_50860100_45_dialog_content = "ฉันแน่นอนดูแก่กว่าสิบปี คุณไม่คิดเช่นนั้นเหรอ?",
  ui_story_5086_50860100_46_dialog_content = "อืม... คิดว่านะ",
  ui_story_5086_50860100_47_dialog_content = "งั้นลองนี่แทนเถอะ!",
  ui_story_5086_50860100_48_dialog_content = "<color=#e8d9bb>เด็กหญิงทันทีปิดตาขวาด้วยมือของเธอ</color>",
  ui_story_5086_50860100_49_dialog_content = "เนื่องจากฉันสามารถเห็นคุณได้เพียงครึ่งเดียว นั่นหมายความว่าฉันต้องถือว่าคุณอายุเพียงครึ่งหนึ่งของอายุปกติของคุณ!",
  ui_story_5086_50860100_50_dialog_content = "ดีเลย, ตอนนี้คุณสามารถเข้าได้ฟรีแล้ว!",
  ui_story_5086_50860100_51_dialog_content = "ฉันขอโทษนะคะ มิส... มายาใช่ไหม? ฉันขอบคุณความคิดดีๆ แต่ฉันมาที่นี่เพื่อธุรกิจที่ค่อนข้างจริงจัง ถ้าคุณยินดีให้ฉันยกเว้น—",
  ui_story_5086_50860100_52_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5086_50860100_53_dialog_content = "อ๊ะ! ฉะ-ฉันขอโทษจริง ๆ!",
  ui_story_5086_50860100_54_dialog_content = "เสียงนั่น...",
  ui_story_5086_50860100_55_dialog_content = "ขอโทษที่ขัดจังหวะค่ะ คุณหนู แต่เพื่อนของฉันเผลอทำป้ายแสดงที่ทางเข้าตกลงไป",
  ui_story_5086_50860100_56_dialog_content = "กรุณาอนุญาตให้เราชดใช้ค่าเสียหายให้คุณเต็มที่",
  ui_story_5086_50860100_57_dialog_content = "ไม่เป็นไรนะ ฉันเพียงวาดป้ายนั้นเอง ฉันก็ดีใจที่คุณทั้งสองไม่ได้รับบาดเจ็บ",
  ui_story_5086_50860100_58_dialog_content = "ฉันขอโทษจริง ๆ สำหรับเรื่องนี้...",
  ui_story_5086_50860100_59_dialog_content = "ไมนอส! ซานาเอะ! นี่คือคุณทั้งสองจริงๆนะ!",
  ui_story_5086_50860100_60_dialog_content = "คุณ PlayerName! ฉันไม่คาดคิดว่าจะได้พบคุณที่นี่... อ๊ะ! ฉันขอโทษ นี่ไม่ใช่วิธีที่ดีในการทักทายเพื่อน!",
  ui_story_5086_50860100_61_dialog_content = "อืม, ค-คุณเป็นไงบ้าง...",
  ui_story_5086_50860100_62_dialog_content = "ฉันสบายดี ซานาเอะ ดีใจที่ได้เจอคุณและมินอสอีกครั้ง",
  ui_story_5086_50860100_63_dialog_content = "สวัสดีครับ คุณ PlayerName. ดีใจที่เห็นคุณสบายดีหลังจากเวลานานนี้",
  ui_story_5086_50860100_64_dialog_content = "นีน่าไม่ได้อยู่กับคุณทั้งหลายรึเปล่าคะ?",
  ui_story_5086_50860100_65_dialog_content = "ฉันกลัวว่าไม่... นางสาวนีน่ากำลังยุ่งอยู่กับการออกแบบใหม่... ดังนั้นเธอขอให้ฉัน... ทำการสำรวจอุตสาหกรรมแทนเธอ",
  ui_story_5086_50860100_66_dialog_content = "อย่างแท้จริง ฉันอยู่ที่นี่เพื่อช่วยเหลือในเรื่องนี้",
  ui_story_5086_50860100_67_dialog_content = "... แน่ใจนะว่าไม่ได้สับสนบทบาทของตัวเอง?",
  ui_story_5086_50860100_68_dialog_content = "อย่าเป็นห่วงนะครับ แม้ว่าซานาเอะยังมีอีกมากที่ต้องเรียนรู้ในฐานะหญิงรับใช้—",
  ui_story_5086_50860100_69_dialog_content = "ในฐานะคนที่อายุเท่ากับหญิงสาวของเรา เธอก็มีความรู้สึกที่สูงส่งและเหมือนกับหญิงสาวของเราในหลาย ๆ ประการเช่นกัน",
  ui_story_5086_50860100_70_dialog_content = "สิ่งที่สำคัญที่สุด อย่างไรก็ตาม คือความจริงที่นางสาวนีน่ายินดีที่จะวางความไว้ใจในตัวเธอ",
  ui_story_5086_50860100_71_dialog_content = "ตราบใดที่เธอยังคงทำตามความคาดหวังของท่านหญิงของเรา ฉันไม่มีเหตุผลใดๆที่จะแทรกแซงหน้าที่ของเธอ",
  ui_story_5086_50860100_72_dialog_content = "ท่านหญิงต้องการที่จะเข้ามามีส่วนร่วมในอุตสาหกรรมนี้ แต่ในฐานะพ่อบ้านของตระกูลแอนเดอร์เซน ถ้าฉันค้นพบว่ามีปัจจัยที่ไม่เสถียรมากเกินไปที่มีผล...",
  ui_story_5086_50860100_73_dialog_content = "สายตาของคุณกลายเป็นน่ากลัวขึ้นอย่างรวดเร็ว มินอส",
  ui_story_5086_50860100_74_dialog_content = "เช่นนั้นหรือ? ถ้างั้นโปรดยกโทษในความหยาบคายของฉัน ฉันหมายความว่าฉันจะดำเนินการแก้ไขถ้าเป็นอย่างนั้น",
  ui_story_5086_50860100_75_dialog_content = "<color=#e8d9bb>จู่ ๆ ก็ได้ยินเสียงวุ่นวายดังขึ้นนอกประตู—</color>",
  ui_story_5086_50860100_76_dialog_content = "อะไรกำลังเกิดขึ้นข้างนอก?",
  ui_story_5086_50860100_77_dialog_content = "มายา มาเร็ว! มีคนที่ดูน่าสงสัยกำลังพยายามเข้าไปในตู้ปลา!",
  ui_story_5086_50860100_78_dialog_content = "<color=#e8d9bb>สองลูกเล็กเด็กแดงปรากฏตัวที่ประตู อุตสาหะปิดทางสองคนที่แต่งตัวหนัก ๆ จากการเข้ามา.</color>",
  ui_story_5086_50860100_79_dialog_content = "สกาโด! เซบาสเตียน! จัดรูปแบบการป้องกัน! อย่าให้ทั้งสองคนนั้นบุกล็อบบี้ได้!",
  ui_story_5086_50860100_80_dialog_content = "พูดง่ายกว่าทำ ฟรูด! ตัวเตี้ยนั่นไม่น่าจะเป็นปัญหา แต่เราจะหยุดตัวสูงๆนั่นจากการเข้ามาได้อย่างไรล่ะ?",
  ui_story_5086_50860100_81_dialog_content = "หนู... นี่จบจริงๆหรือเปล่า?",
  ui_story_5086_50860100_82_dialog_content = "ฮีฮีฮี ลูกเล็กเด็กแดงพวกคุณมีพลังงานมากเลย แต่ฉันสามารถรับประกันได้ว่า เราไม่ใช่คนร้ายนะ",
  ui_story_5086_50860100_83_dialog_content = "นั่นคือสิ่งที่คนชั่วจะพูด!",
  ui_story_5086_50860100_84_dialog_content = "แถมอีก ใครจะใส่เสื้อผ้ามากขนาดนี้ไปสวนสัตว์น้ำ เมื่ออากาศข้างนอกร้อนขนาดนี้ล่ะ?",
  ui_story_5086_50860100_85_dialog_content = "ถ้าคุณยังไม่สามารถเห็นความเจ๋งของชุดของเรา แสดงว่าคุณยังมีทางที่ยาวไกลก่อนที่จะเรียกตัวเองว่าเป็นนักต้มตุ๋นเหมือนเรา",
  ui_story_5086_50860100_86_dialog_content = "ฟึบ-อะไรนะ?",
  ui_story_5086_50860100_87_dialog_content = "ว่าไง—คุณหมายความว่าคุณไม่รู้เกี่ยวกับอาชีพที่เจ๋งที่สุดในโลกหรือ? ถ้างั้นขอฉัน—",
  ui_story_5086_50860100_88_dialog_content = "เอาล่ะ สองคนนั่น พอแล้วนะ",
  ui_story_5086_50860100_89_dialog_content = "!",
  ui_story_5086_50860100_90_dialog_content = "<color=#e8d9bb>ในขณะที่พวกเขากำลังทะเลาะกัน ไม่รู้ว่าอย่างไร มายาก็สามารถปรากฏตัวขึ้นมาเบื้องหลังพวกเขาได้</color>",
  ui_story_5086_50860100_91_dialog_content = "<color=#e8d9bb>ด้วยการเคลื่อนไหวที่คล่องแคล่วเพียงครั้งเดียว เธอจับแว่นกันแดดและหน้ากากออกจากใบหน้าของพวกเขา</color>",
  ui_story_5086_50860100_92_dialog_content = "โกลดี้? ซาดี?",
  ui_story_5086_50860100_93_dialog_content = "โอ๊ะ ไม่นะ",
  ui_story_5086_50860100_94_dialog_content = "เธอแอบเข้ามาข้างเราโดยที่เราไม่ได้สังเกตเลย! คุณคือใครในโลกนี้?",
  ui_story_5086_50860100_95_dialog_content = "ฉันชื่อมายาค่ะ ฉันเป็นพนักงานที่นี่ในอควาเรียมค่ะ",
  ui_story_5086_50860100_96_dialog_content = "ฉันขอโทษ แต่ฉันต้องขอให้คุณหลีกเลี่ยงการใส่เสื้อผ้าที่ดูน่ากลัวอย่างนี้ที่นี่ เพราะมีเด็ก ๆ วิ่งเล่นอยู่ในสถานีสัตว์น้ำเยอะมาก คุณรู้ไหม",
