  ui_story_5086_50860701_77_dialog_content = "ผู้มาเยือนที่หายไปนั้นได้เจอกับอิคลิพไซท์และถูกโจมตีในขณะที่พยายามหนี...",
  ui_story_5086_50860702_1_dialog_content = "จนกว่าเราจะค้นหาทุกมุมของตู้ปลานี้ ฉันไม่สามารถปฏิเสธความเป็นไปได้ว่าจะมีห้องที่ถูกซ่อนอยู่ในที่นี้",
  ui_story_5086_50860702_2_dialog_content = "อย่างไรก็ตาม เราต้องเผชิญกับปัญหาด่วนอีกอย่าง...",
  ui_story_5086_50860702_3_dialog_content = "เราเสร็จแล้วหรือยัง? เราต้องเสียเวลาอยู่ที่นี่อีกนานแค่ไหน?",
  ui_story_5086_50860702_4_dialog_content = "เรื่องนี้ให้ทหารยามเมืองจัดการเถอะ การจัดการเรื่องคนหายนี่เป็นหน้าที่ของพวกเขาไม่ใช่หรือ?",
  ui_story_5086_50860702_5_dialog_content = "ฉันเข้าใจความกังวลของทุกคน ทหารยามเมืองได้รับการแจ้งเตือนแล้ว แต่จะดีที่สุดถ้าทุกคนยังคงอยู่ที่นี่จนกว่าพวกเขาจะมาถึง",
  ui_story_5086_50860702_6_dialog_content = "ต้องรับรู้ว่ามีบางอย่างผิดปกติกับที่นี่อย่างมาก และฉันไม่คิดจะอยู่เพื่อหาคำตอบว่ามันคืออะไร! ฉันจะแน่นอนที่จะบอกเพื่อน ๆ ของฉันให้หลีกเลี่ยงที่นี่ด้วย!",
  ui_story_5086_50860702_7_dialog_content = "ได้โปรดอย่าพูดอย่างนั้น! เรากำลัง...",
  ui_story_5086_50860702_8_dialog_content = "ด้วยสถานการณ์ปัจจุบัน เราไม่มีเวลาเพียงพอในการทำการตรวจสอบอย่างละเอียดเช่นนี้",
  ui_story_5086_50860702_9_dialog_content = "ลูกค้าเริ่มหงุดหงิดแล้ว...",
  ui_story_5086_50860702_10_dialog_content = "กรุณายกโทษให้ฉันด้วย.",
  ui_story_5086_50860702_11_dialog_content = "ว่าไง—เฮ้!",
  ui_story_5086_50860702_12_dialog_content = "มันเป็นอะไร มินอส? ทำไมคุณถึงดันฉันแบบนั้น...",
  ui_story_5086_50860702_13_dialog_content = "มีอะไรบางอย่างผิดปกติ, PlayerName?",
  ui_story_5086_50860702_14_dialog_content = "(โอ้ไม่ ทุกคนกำลังเอาความสนใจมาที่ฉันเพราะฉันโดดเข้าไปอย่างกะทันหัน!)",
  ui_story_5086_50860702_15_dialog_content = "ฮ่าฮ่า... ข-ขอโทษที่ขัดจังหวะ...",
  ui_story_5086_50860702_16_dialog_content = "แต่ฉันคิดว่าฉันรู้วิธีที่จะเปิดเผยความจริง!",
  ui_story_5086_50860702_17_dialog_content = "?!",
  ui_story_5086_50860702_18_dialog_content = "(ว-นั่นเสียงฉันเหรอ?!)",
  ui_story_5086_50860702_19_dialog_content = "ที่น่าตื่นตาตื่นใจ, PlayerName!",
  ui_story_5086_50860702_20_dialog_content = "ในขณะที่ทุกคนยังคงตื่นตระหนก คุณก็เริ่มทำงานหนักเพื่อพยายามแก้ปริศนาอยู่แล้วใช่ไหม?",
  ui_story_5086_50860702_21_dialog_content = "ความสามารถของคุณในการควบคุมสถานการณ์นั้นน่าประทับใจมาก!",
  ui_story_5086_50860702_22_dialog_content = "ว้าว, PlayerName! ฉันไม่รู้เลยว่าคุณอยากเป็นนักสืบแทนที่จะเป็นผู้กล้าหาญเหมือนฉัน!",
  ui_story_5086_50860702_23_dialog_content = "N-ตอนนี้ รอสักครู่! ไม่ใช่ฉัน—",
  ui_story_5086_50860702_24_dialog_content = "นั่นไม่ใช่ฉันที่พูดโม้มวยนะ!",
  ui_story_5086_50860702_25_dialog_content = "เฮ้! อย่ามาขัดจังหวะฉัน—",
  ui_story_5086_50860702_26_dialog_content = "เพราะฉันกำลังจะชี้แจงผู้ร้ายตัวจริงให้เห็น!",
  ui_story_5086_50860702_27_dialog_content = "... อะไร?!?",
  ui_story_5086_50860702_28_dialog_content = "เอ่อ? คุณจริง ๆ แล้วแปลกใจกับด้านอื่น ๆ ของตัวเองขนาดนี้เหรอ, PlayerName?",
  ui_story_5086_50860702_29_dialog_content = "คุณคิดว่าคุณคือใคร ที่กำลังแสร้งเป็นนักสืบในตอนนี้? อ่านสถานการณ์ดีๆ นายวัยรุ่นเจ้าอายุ!",
  ui_story_5086_50860702_30_dialog_content = "อ๊ะ ปล่อยเขาไปสิ เขาก็แค่เด็กคนหนึ่งเท่านั้นเอง",
  ui_story_5086_50860702_31_dialog_content = "(ทุกคนคงคิดว่าฉันเป็นคนบ้าแล้ว!)",
  ui_story_5086_50860702_32_dialog_content = "แต่ฉันจริง ๆ แล้ว—",
  ui_story_5086_50860702_33_dialog_content = "อะแฮ่ม",
  ui_story_5086_50860702_34_dialog_content = "(มินอส?!)",
  ui_story_5086_50860702_35_option_content = "สแกนพลังจิต!",
  ui_story_5086_50860702_36_dialog_content = "(นี่มันเกิดอะไรขึ้น มินอส?)",
  ui_story_5086_50860702_37_dialog_content = "(ฉันจะขอโทษคุณอย่างเต็มที่ในภายหลังนะ มิตร. แต่ในฐานะพ่อบ้าน ฉันไม่ค่อยเหมาะกับการยืนอยู่ในแสงสปอตไลท์น่ะ)",
  ui_story_5086_50860702_38_dialog_content = "(ด้วยเหตุนี้ ฉันต้องขอให้คุณร่วมมือกับฉัน ดังที่มานาเอะทำกับซานาเอะ)",
  ui_story_5086_50860702_39_dialog_content = "(ดังนั้นคุณต้องการให้ฉันทำหน้าที่เป็นหุ่นเชิดของคุณรึ?)",
  ui_story_5086_50860702_40_dialog_content = "(ถ้าคุณต้องการ, ใช่.)",
  ui_story_5086_50860702_41_dialog_content = "กรุณาฟังทุกคน! ฉันได้ค้นพบสิ่งบางอย่างในทางเดินที่อยู่ทางนั้น...",
  ui_story_5086_50860702_42_dialog_content = "... ดังนั้นเมื่อคุณนำทุกอย่างมาประกอบกัน โดยเฉพาะรอยเลือดบนเสา มันเป็นไปได้ว่าบุคคลที่หายไปได้รับการโจมตี",
  ui_story_5086_50860702_43_dialog_content = "เริ่มตั้งแต่บ่ายวันนี้ ยังไม่มีใครที่ออกจากอควาเรียมเลย นั่นก็หมายความว่า—",
  ui_story_5086_50860702_44_dialog_content = "ผู้ร้ายยังไม่ได้ออกไป หรือกล่าวอีกนัยหนึ่ง... ฆาตกรอยู่ที่ใดที่หนึ่งในหมู่เรา",
  ui_story_5086_50860702_45_dialog_content = "เอาจริงดิ, เด็ก! นี่เธอจะกล่าวหาพวกเราจริง ๆ ใช่มั้ยเนี่ย?!",
  ui_story_5086_50860702_46_dialog_content = "การที่คุณต้องการความสนใจไปถึงขั้นนี้มันเกินไปแล้ว! นอกจากนี้ คุณจริง ๆ คิดว่าคุณสามารถสร้างคดีด้วยหลักฐานที่บอบบางเช่นนี้ได้หรือไม่?!",
  ui_story_5086_50860702_47_dialog_content = "ว่าแล้วเชียว! ฉันรู้ว่ามีบางอย่างผิดปกติกับตู้ปลานี้!",
  ui_story_5086_50860702_48_dialog_content = "ตอนที่อิคลิพไซท์โจมตีเมืองฮาร์เบอร์ พวกเขาคงได้เปลี่ยนพนักงานที่นี่ให้กลายเป็นพวกของพวกเขาเอง!",
  ui_story_5086_50860702_49_dialog_content = "อะไร!? ฉันไม่ใช่อิคลิพไซท์เลย! และอย่ามาชี้นิ้วตำหนินาง Stellandine หรือพนักงานท่านอื่นๆ ของเรานะ!",
  ui_story_5086_50860702_50_dialog_content = "ใช่แล้ว! คุณไม่สามารถกล่าวหามายาหรือสเตลลาไดน์แบบนั้นได้ เฉพาะเมื่อคุณไม่รู้อะไรเกี่ยวกับพวกเขาเลย!",
  ui_story_5086_50860702_51_dialog_content = "PlayerName ในขณะที่ฉันขอขอบคุณสำหรับความช่วยเหลือของคุณในการสืบสวนครั้งนี้ ฉันต้องขอให้คุณงดการกล่าวหาลูกค้าของเราโดยไม่มีเหตุผล...",
  ui_story_5086_50860702_52_dialog_content = "(เธอถูกต้อง มินอส! ฉันบอกคุณว่าฉันรับรู้ถึง Eclipsite ก่อนหน้านี้ ดังนั้นหมายความว่าผู้ร้ายไม่ใช่หนึ่งในพวกเขาใช่ไหม?)",
  ui_story_5086_50860702_53_dialog_content = "(ทุกคนเริ่มสงสัยกันเพราะสิ่งที่คุณพูด!)",
  ui_story_5086_50860702_54_dialog_content = "(นี่เป็นส่วนหนึ่งของเหตุผลที่ฉันขอความร่วมมือจากคุณ)",
  ui_story_5086_50860702_55_dialog_content = "(คุณเป็นหนุ่มน้อยที่ฉลาด แต่ความขาดแคลนในการสงสัยของคุณบางครั้งอาจทำให้เป็นห่วง)",
  ui_story_5086_50860702_56_dialog_content = "(หือ?)",
  ui_story_5086_50860702_57_dialog_content = "แน่นอนฉันสามารถกล่าวหาสิ่งเหล่านี้ได้! ฉันเป็น Caelestite อยู่ดีนะ!",
  ui_story_5086_50860702_58_dialog_content = "ฉันยังเป็นเพื่อนสนิทของท่านหญิงคาร์ลีน อัศวินแห่งลูโมโพลิสจะยินดีที่จะยืนยันทุกอย่างนี้เมื่อพวกเขามาถึงที่นี่",
  ui_story_5086_50860702_59_dialog_content = "ในฐานะเคเลสไทต์และพันธมิตรที่ไว้วางใจของท่านหญิงคาร์ลีน มันเป็นเรื่องปกติที่ฉันจะอยากจับกุมอาชญากรนี้ คุณไม่คิดเช่นนั้นหรือครับ?",
  ui_story_5086_50860702_60_dialog_content = "ทั้งหมดที่ฉันต้องทำคือจับมือกับทุกคนที่อยู่ที่นี่ และพลังจิตของฉันจะช่วยให้ฉันหาผู้ร้ายที่แท้จริงได้",
  ui_story_5086_50860702_61_dialog_content = "แล้วถ้าคุณไม่พบผู้ร้ายอยู่ในหมู่เราล่ะ?",
  ui_story_5086_50860702_62_dialog_content = "แล้วนั่นก็จะเป็นผลลัพธ์ที่ดีที่สุดที่เป็นไปได้ คุณเห็นด้วยไหม?",
  ui_story_5086_50860702_63_dialog_content = "เอ๋...?",
  ui_story_5086_50860702_64_dialog_content = "แน่นอนว่าถ้าเราสามารถหาผู้ร้ายออกมาได้ที่นี่ที่นี้ก็จะดีมาก",
  ui_story_5086_50860702_65_dialog_content = "แต่ถ้าฉันไม่พบเขาอยู่ในหมู่คุณ นั่นแสดงว่าไม่มีใครในหมู่คุณเป็นฆาตกร ใช่ไหม?",
  ui_story_5086_50860702_66_dialog_content = "ดังนั้นฉันจะหาอาชญากรหรือพิสูจน์ความบริสุทธิ์ของทุกคน มันเป็นสถานการณ์ที่ทุกฝ่ายได้ผลประโยชน์ คุณไม่คิดเช่นนั้นหรือ?",
  ui_story_5086_50860702_67_dialog_content = "ก็มีเหตุผลมากนะ! ที่นี่ ให้ฉันไปก่อน!",
  ui_story_5086_50860702_68_dialog_content = "ฉันคิดว่าคุณพูดถูก... โอเค, ฉันจะร่วมมือ",
  ui_story_5086_50860702_69_dialog_content = "(ว้าว... ทุกคนที่ไม่ยอมทำงานร่วมกันเหล่านี้กำลังต่อแถวมาช่วยเหลืออย่างกะทันหันนะคะ.)",
  ui_story_5086_50860702_70_dialog_content = "(ฉันรู้ว่าฉันควรจะเป็นตุ๊กตาที่นี่ แต่มินอสกลับควบคุมทุกคนในห้องด้วยจมูกของพวกเขา)",
  ui_story_5086_50860702_71_dialog_content = "(นอกจากนี้ ดูเหมือนว่าไม่มีใครคิดถึงความเป็นไปได้ที่ฉันจริง ๆ แล้วไม่รู้อะไรเลย หรือว่าฉันไม่มีทางพิสูจน์ความบริสุทธิ์ของใคร...)",
  ui_story_5086_50860702_72_dialog_content = "(การตอบสนองที่เป็นธรรมชาติ สุดท้ายแล้ว คนเรามักจะมองเห็นสิ่งต่างๆในมุมสั้นๆได้ง่ายๆในสถานการณ์ที่เครียดเช่นนี้ เมื่อเกิดสิ่งนั้นขึ้น พวกเขาจะเห็นสิ่งต่างๆเพียงแค่เป็นสีดำและขาวเท่านั้น)",
  ui_story_5086_50860702_73_dialog_content = "(แต่ในระยะเวลานี้ ขอให้คุณอย่าเตือนพวกเขาเกี่ยวกับความเป็นไปได้นั้น)",
  ui_story_5086_50860702_74_dialog_content = "(ด้วยสถานการณ์ปัจจุบันของเรา ฉันเชื่อว่าการรวมทุกคนภายใต้เป้าหมายร่วมเป็นสิ่งที่สำคัญยิ่ง)",
  ui_story_5086_50860702_75_dialog_content = "(ฉันรู้... แต่ว่า...)",
  ui_story_5086_50860702_76_dialog_content = "(พวกเขาทั้งหมดต้องการให้ฉันจับมือพวกเขาตอนนี้! ฉันจริงๆ ต้องใช้พลังของฉันกับทุกคนใช่ไหม?)",
  ui_story_5086_50860702_77_dialog_content = "(ไม่เลยเพื่อนของฉัน.)",
  ui_story_5086_50860702_78_dialog_content = "(ทั้งหมดนี้ ฉันแค่อยากจะสังเกต...)",
  ui_story_5086_50860702_79_dialog_content = "(คนไหนในพวกเขาที่จะแสดงพฤติกรรมที่ไม่ปกติในช่วงเวลาสำคัญเช่นนี้.)",
  ui_story_5086_50860702_80_dialog_content = "<color=#e8d9bb>อยู่ ๆ แถวคนที่รอจับมือก็หยุดทันที</color>",
  ui_story_5086_50860702_81_dialog_content = "เกิดอะไรขึ้น มายา? ถึงตาคุณแล้วนะ คุณรู้ไหม",
  ui_story_5086_50860702_82_dialog_content = "ฉัน......",
  ui_story_5086_50860702_83_dialog_content = "(ถูกต้อง; มายาคิดว่าพลังของฉันจะทำให้บรรพบุรุษสับสนอย่างใดอย่างหนึ่ง)",
  ui_story_5086_50860702_84_dialog_content = "ไม่ต้องห่วงนะ มายา ฉัน...",
  ui_story_5086_50860702_85_dialog_content = "<color=#e8d9bb>เปรี๊ยะ!</color>",
  ui_story_5086_50860702_86_dialog_content = "เกิดอะไรขึ้น?! ใครปิดไฟเข้าน่ะ?!",
  ui_story_5086_50860702_87_dialog_content = "เข้าแถวเรียงและใจเย็นๆ นะทุกคน—",
  ui_story_5086_50860702_88_dialog_content = "มีคนล็อกทางเข้าไว้! เราทุกคนติดอยู่ในนี้แล้ว!",
  ui_story_5086_50860702_89_dialog_content = "ไปให้พ้น! ไม่มีประตูไหนต้านฉันได้—",
  ui_story_5086_50860702_90_dialog_content = "<color=#e8d9bb>พลัก!</color>",
  ui_story_5086_50860702_91_dialog_content = "<color=#e8d9bb>ในความสับสน, เสียงกระจกแตกทะลุอากาศ</color>",
  ui_story_5086_50860702_92_dialog_content = "<color=#e8d9bb>ก่อนที่ใครจะไหวตัวทัน ถังที่ล้อมรอบล็อบบี้ของตู้ปลาก็ระเบิดขึ้น</color>",
  ui_story_5086_50860702_93_dialog_content = "<color=#e8d9bb>ล็อบบี้ถูกน้ำเย็นและปลามากมายท่วมทันที.</color>",
  ui_story_5086_50860801_1_dialog_content = "PlayerName—!",
  ui_story_5086_50860801_2_dialog_content = "อ๊ากกก... ไอ ไอ ไอ ไอ—",
  ui_story_5086_50860801_3_dialog_content = "คุณโอเคมั้ยเนี่ย?",
  ui_story_5086_50860801_4_dialog_content = "ใช่ ฉันแค่สำลักน้ำเข้าไปหน่อย นั่นแหละ... ขอบคุณที่ช่วยชีวิตฉันนะ",
  ui_story_5086_50860801_5_dialog_content = "อย่าขอบคุณฉัน ขอบคุณโกลดี้",
  ui_story_5086_50860801_6_dialog_content = "ทุกคนถูกพัดไปเมื่อถังแตก แต่เธอสามารถจับเราทั้งสองขึ้นจากน้ำได้",
  ui_story_5086_50860801_7_dialog_content = "มันเป็นแค่โชคที่โง่เขลา นั่นแหละทั้งหมด",
  ui_story_5086_50860801_8_dialog_content = "ฉันอยู่ห่างจากถังน้ำมันที่ระเบิดมากที่สุด ดังนั้นฉันมีเวลามากขึ้นเล็กน้อยในการตอบสนอง",
  ui_story_5086_50860801_9_dialog_content = "แต่ฉันไม่สามารถเห็นอะไรในความมืดเมื่อสักครู่ ดังนั้นฉันจึงทนทานกับสองคนที่ใกล้ที่สุดกับฉัน",
  ui_story_5086_50860801_10_dialog_content = "โชคดีที่ขณะที่กระแสน้ำกำลังพัดพาเราไป ฉันยังสามารถที่จะทำประตูที่พื้นที่พักผ่อนนี้แตกออก และดึงเราออกจากน้ำได้",
  ui_story_5086_50860801_11_dialog_content = "(นั่นไม่เหมือนเสียงของโชคชะตาที่โง่เขลาเลย โกลดี้...)",
  ui_story_5086_50860801_12_dialog_content = "ยังไง... ทุกอย่างนี้เกิดขึ้นได้ยังไงกัน...?",
  ui_story_5086_50860801_13_dialog_content = "<color=#e8d9bb>น้ำยังคงไหลผ่านรอยร้าวที่ประตู ทำให้ระดับน้ำในห้องเพิ่มขึ้นอย่างทีละน้อย</color>",
  ui_story_5086_50860801_14_dialog_content = "ฉันรู้ว่านี่คือตู้ปลา แต่ทำไมมันถึงรู้สึกเหมือนว่ามีน้ำอยู่ในนี่เป็นปริมาณที่ไม่มีที่สิ้นสุดล่ะ?",
  ui_story_5086_50860801_15_dialog_content = "ดูเหมือนห้องนี้ก็จะไม่อยู่ได้นานแล้วนะ",
  ui_story_5086_50860801_16_dialog_content = "แล้วตอนนี้เราควรทำอย่างไร?",
  ui_story_5086_50860801_17_dialog_content = "ฉันคิดว่าเราต้องหาทางในการรวมกลุ่มกับทุกคนก่อน",
  ui_story_5086_50860801_18_dialog_content = "ช่วย—!",
  ui_story_5086_50860801_19_dialog_content = "มีคนเดือดร้อน!",
  ui_story_5086_50860801_20_dialog_content = "ไม่ต้องกังวล Super Sadie Swashbuckler 666 กำลังจะมาถึงแล้ว!",
  ui_story_5086_50860801_21_dialog_content = "เดี๋ยวนะ—",
  ui_story_5086_50860801_22_dialog_content = "เราจะไปกับคุณ",
  ui_story_5086_50860801_23_dialog_content = "นั่นไง! ดูสิ!",
  ui_story_5086_50860801_24_dialog_content = "<color=#e8d9bb>น้ำในโถงทางเดินมาถึงระดับเอวแล้ว กลุ่มผู้มาเยือนร้องขอความช่วยเหลือจากบนชิ้นไม้ที่ลอยอยู่</color>",
  ui_story_5086_50860801_25_dialog_content = "<color=#e8d9bb>ที่กำลังว่ายมาทางพวกเขาคือฉลามขนาดใหญ่—</color>",
  ui_story_5086_50860801_26_dialog_content = "หายไปเถอะ คุณคนอวดผลิต!",
  ui_story_5086_50860801_27_dialog_content = "<color=#e8d9bb>อย่างน่าประหลาด การโจมตีของซาดีทำให้ฉลามถอยหลังไปหลายฟุต</color>",
  ui_story_5086_50860801_28_dialog_content = "อย่าห่วง, คนเจ้าชู้เสมอมาจะปกป้องผู้ที่ต้องการความช่วยเหลือ!",
  ui_story_5086_50860801_29_dialog_content = "ที่นี่, PlayerName! จับสิ่งนี้ไว้!",
  ui_story_5086_50860801_30_dialog_content = "แห่งปลา? คุณได้มาจากที่ไหนเนี่ย?",
  ui_story_5086_50860801_31_dialog_content = "ฉันเกือบจะติดขัดในมันระหว่างทางมาที่นี่ ฉันคิดว่ามันอาจจะมีประโยชน์ในภายหลัง ดังนั้นฉันจึงเอามันมาด้วย",
  ui_story_5086_50860801_32_dialog_content = "มาใช้มันกันเถอะ!",
  ui_story_5086_50860801_33_dialog_content = "คิดว่าเราสามารถทำสำเร็จได้ด้วยกันไหม ซาดี?",
