  ui_story_5086_50860801_37_dialog_content = "<color=#e8d9bb>ซาดียกไม้เบสบอลขึ้น</color>",
  ui_story_5086_50860801_38_dialog_content = "สอง.",
  ui_story_5086_50860801_39_dialog_content = "<color=#e8d9bb>โกลดี้และฉันเดินหน้าอย่างเงียบๆ</color>",
  ui_story_5086_50860801_40_dialog_content = "หนึ่ง!",
  ui_story_5086_50860801_41_dialog_content = "<size=50>คุณไปให้พ้นจากที่นี่—!</size>",
  ui_story_5086_50860801_42_dialog_content = "<color=#e8d9bb>ฉลามหล่นลงไปในอวนที่รออยู่อย่างสมบูรณ์แบบ</color>",
  ui_story_5086_50860801_43_dialog_content = "ทำได้ดีมาก ทุกคน",
  ui_story_5086_50860801_44_dialog_content = "คุณแทบจะไม่เหงื่อออกเลยเมื่อกี้ โกลดี้... ฉันจริงๆ แย่เลยใช่ไหม?",
  ui_story_5086_50860801_45_dialog_content = "ฮิฮิ",
