  ui_story_5086_50860801_47_dialog_content = "<color=#e8d9bb>อย่างกะทันหัน เงามืดขนาดใหญ่ปรากฏขึ้นในน้ำด้านหลังซาดี</color>",
  ui_story_5086_50860801_48_dialog_content = "ออกจากที่นั่น ซาดี!",
  ui_story_5086_50860801_49_dialog_content = "กรร",
  ui_story_5086_50860801_50_dialog_content = "!",
  ui_story_5086_50860801_51_dialog_content = "(ฉ-ฉันมาช้าไป...)",
  ui_story_5086_50860801_52_dialog_content = "<size=50>คำตัดสินอย่างรวดเร็ว.</size>",
  ui_story_5086_50860801_53_dialog_content = "<size=50>มานาเอะไร้พ่าย!</size>",
  ui_story_5086_50860801_54_dialog_content = "ขออภัยที่ใช้เวลานานเกินไปนะคะทุกคน",
  ui_story_5086_50860801_55_dialog_content = "ฉันแค่ออกไปเรียกซานาเอะมา แต่ดูเหมือนว่าจะมีสัตว์น่าสะพรึงกลัวหลายตัวปรากฏตัวขึ้นในช่วงที่เราไม่อยู่",
  ui_story_5086_50860801_56_dialog_content = "<color=#e8d9bb>มินอสยืนอย่างสมบูรณ์แบบบนสายริบบิ้นที่กลางอากาศ และให้การโค้งสุภาพ</color>",
  ui_story_5086_50860801_57_dialog_content = "<color=#e8d9bb>ซานาเอะที่มีหน้าตาที่เศร้าสลดอยู่ภายใต้แขนซ้ายของเขา</color>",
  ui_story_5086_50860801_58_dialog_content = "เอิ่ม... ข-ขอโทษนะครับ! ผมไม่ได้ตั้งใจจะหลับผ่านทุกอย่าง!",
  ui_story_5086_50860801_59_dialog_content = "B-แต่ตอนนี้ฉันอยู่ที่นี่แล้ว ฉันจะทำทุกอย่างที่ฉันสามารถทำเพื่อแก้ไขสถานการณ์!",
  ui_story_5086_50860801_60_dialog_content = "นั่นดีมากแล้ว ซานาเอะ ตอนนี้เริ่มทำเถอะ ถ้าคุณไม่มีปัญหา",
  ui_story_5086_50860801_61_dialog_content = "ห๊ะ",
