  ui_story_5086_50860802_2_dialog_content = "สุดท้ายแล้ว... มีอิคลิพไซท์ซ่อนตัวใต้น้ำเท่าไหร่เนี่ย?",
  ui_story_5086_50860802_3_dialog_content = "อาจจะไม่พิสูจน์ได้ถึงทฤษฎีของคุณเกี่ยวกับห้องที่ซ่อนอยู่ในตู้ปลา แต่นี่ก็ยังคือหลักฐานที่น่าสนใจอยู่ดี",
  ui_story_5086_50860802_4_dialog_content = "นี่จะเป็นเวลาที่เหมาะสมสำหรับสิ่งนั้นจริง ๆ หรือไม่ มินอส?",
  ui_story_5086_50860802_5_dialog_content = "แน่นอน. จนกว่าความจริงจะเป็นที่ชัดเจน เราจะต้องไม่ปล่อยให้การสืบสวนของเราหลุดออกไปจากสายตา",
  ui_story_5086_50860802_6_dialog_content = "เดี๋ยวก่อน!",
  ui_story_5086_50860802_7_dialog_content = "ฉันไม่รู้ว่าพวกคุณกำลังพูดถึงอะไร แต่ฉลามนั่นกำลังพุ่งตรงมาที่เรา!",
  ui_story_5086_50860802_8_dialog_content = "<color=#e8d9bb>เสียงของตาข่ายตกปลาที่ขาดแตกเต็มทั้งห้องเมื่อฉลามหลุดออกจากข้อจำกัดของมัน!</color>",
  ui_story_5086_50860802_9_dialog_content = "<color=#e8d9bb>ที่ไกลขึ้น มีเงาที่ดูน่ากลัวมากขึ้นและมากขึ้นปรากฏอยู่ใต้ผิวน้ำ</color>",
  ui_story_5086_50860802_10_dialog_content = "ข้างหลังเรา! และมีพวกมันมากขึ้นอีก!",
  ui_story_5086_50860802_11_dialog_content = "เราจะถูกกินทั้งเป็นแน่!!!",
  ui_story_5086_50860802_12_dialog_content = "... ทุกคนยังมีกำลังพอสู้ต่อไหม?",
  ui_story_5086_50860802_13_dialog_content = "ฉันเหนื่อยมาก แต่การสู้จนถึงที่สุดเท่านั้นที่เป็นทางออก",
  ui_story_5086_50860802_14_dialog_content = "ตราบใดที่ยังมีแฟนตัวยงอยู่ ไอดอลจะไม่สามารถแสดงความเหนื่อยล้าแม้แต่น้อย!",
  ui_story_5086_50860802_15_dialog_content = "หญิงรับใช้และพ่อบ้านไม่มีความแตกต่างกัน แต่...",
  ui_story_5086_50860802_16_dialog_content = "<color=#e8d9bb>เสียงที่คุ้นเคยของหอยสังข์ก้องขึ้น</color>",
  ui_story_5086_50860802_17_dialog_content = "<color=#e8d9bb>ฉลามที่กำลังวิ่งเต็มที่หันทันทีและว่ายน้ำในทิศทางของเสียงดนตรี.</color>",
  ui_story_5086_50860802_18_dialog_content = "ดูเหมือนว่าเราสามารถลดอาวุธลงได้แล้วนะ",
  ui_story_5086_50860802_19_dialog_content = "ตามมันไปเถอะ",
  ui_story_5086_50860802_20_dialog_content = "<color=#e8d9bb>แสงที่สะท้อนโดยชิ้นส่วนของกระจกที่แตกเป็นชิ้นๆ ทำให้แสงที่มัวแววเต็มทั้งอาคารสัตว์น้ำ</color>",
  ui_story_5086_50860802_21_dialog_content = "<color=#e8d9bb>ร่างเงาที่ไม่ชัดเจนของมายาสามารถมองเห็นได้ว่ายืนอยู่ที่ปลายทางของโถงทางเดินที่มืดมิด</color>",
  ui_story_5086_50860802_22_dialog_content = "<color=#e8d9bb>หลงใหลในท่วงทำนองที่สวยงามของหอยสังข์ สัตว์น้ำที่มีรูปร่างและขนาดต่าง ๆ มากมายว่ายน้ำเข้าหาเธอ</color>",
  ui_story_5086_50860802_23_dialog_content = "มายา—",
  ui_story_5086_50860802_24_dialog_content = "อย่าขยับนะ!",
  ui_story_5086_50860802_25_dialog_content = "นางสเตลแลนดีน? และฟรูด, และผู้มาเยือนท่านอื่นๆ... ขอบคุณสวรรค์ ท่านทั้งหมดยังปลอดภัยดี!",
  ui_story_5086_50860802_26_dialog_content = "คุณเรียกนี้ว่า \"ไม่เป็นไร\" หรือ?! คุณไม่เห็นเหรอว่าเด็กหญิงคนนั้นสั่งให้ปลาทั้งหมดโจมตีเรา?!",
  ui_story_5086_50860802_27_dialog_content = "ถ้าเจ้าของตู้ปลาไม่มาปกป้อง เราคงกลายเป็นเหยื่อปลาตอนนี้แล้ว!",
  ui_story_5086_50860802_28_dialog_content = "คนหายจากครั้งก่อนน่าจะเป็นเหยื่อของเด็กผู้หญิงคนนั้นด้วย! ถ้าพวกคุณคิดว่าพวกคุณแข็งแกร่ง ไปจัดการกับเธอทันที!",
  ui_story_5086_50860802_29_dialog_content = "ห๊ะ",
  ui_story_5086_50860802_30_dialog_content = "เปล่านะ...",
  ui_story_5086_50860802_31_dialog_content = "เธอกำลังพยายามหนี!",
  ui_story_5086_50860802_32_dialog_content = "...",
  ui_story_5086_50860802_33_dialog_content = "เดี๋ยวสิ มายา!",
  ui_story_5086_50860802_34_dialog_content = "อ๊ะ, ฉันว่ายน้ำไม่ได้เร็วพอ! ฉันตามไม่ทัน—",
  ui_story_5086_50860802_35_dialog_content = "ฝากนี้ให้ฉันดูแลนะคุณ PlayerName โปรดดูแลคนอื่น ๆ ที่ฝั่งของฉัน",
  ui_story_5086_50860802_36_dialog_content = "<color=#e8d9bb>มินอสกระโดดอย่างแม่นยำข้ามซากปรักหักพังที่ลอยอยู่และไปตามมายา</color>",
  ui_story_5086_50860802_37_dialog_content = "... เราไม่สามารถอยู่ที่นี่ต่อไปได้ เราต้องหาที่ปลอดภัยให้ทุกคนหลบภัย",
  ui_story_5086_50860802_38_dialog_content = "น้ำยังไม่ได้ท่วมถึงชั้นสอง เราควรพยายามขึ้นไปที่นั่น",
  ui_story_5086_50860802_39_dialog_content = "ฉันไม่ไปกับคุณทุกคน! ฉันต้องไปหานาง Maya!",
  ui_story_5086_50860802_40_dialog_content = "ขอโทษนะ เด็กน้อย แต่เราควรจะคุยเรื่องนี้กันเมื่อทุกคนปลอดภัยแล้ว",
  ui_story_5086_50860802_41_dialog_content = "ไม่มีทาง! คุณเป็นท่านหญิงที่ไม่ดี ดังนั้นเอามือออกจากฉัน!",
