  ui_story_5086_50860802_43_dialog_content = "ฉันรู้ว่าคุณเศร้านะ น้องหนู แต่คุณต้องคิดเชิงบวกในช่วงเวลาแบบนี้! ถ้าคุณไม่ยิ้มเมื่อสถานการณ์ยากลำบาก คุณจะไม่มีความสุขนานนักหรอก!",
  ui_story_5086_50860802_44_dialog_content = "B-แต่พวกเขาพูดเรื่องร้ายๆเกี่ยวกับมิสมายาทั้งหมดนั่นสิ!",
  ui_story_5086_50860802_45_dialog_content = "ฉันรู้ และการพูดแบบนั้นไม่เหมาะสมกับใครเลย แต่คุณไม่เห็นด้วยกับพวกเขาเลยใช่ไหม?",
